import{_t as e,it as t,n,rt as r}from"./chunks/framework.CzJE1L4g.js";var i=JSON.parse(`{"title":"@svta/cml-utils changelog","description":"","frontmatter":{},"headers":[],"relativePath":"packages/utils/changelog.md","filePath":"packages/utils/changelog.md"}`),a={name:`packages/utils/changelog.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="svta-cml-utils-changelog" tabindex="-1">@svta/cml-utils changelog <a class="header-anchor" href="#svta-cml-utils-changelog" aria-label="Permalink to “@svta/cml-utils changelog”">​</a></h1><p>All notable changes to this project will be documented in this file.</p><p>The format is based on <a href="https://keepachangelog.com/en/1.0.0/" target="_blank" rel="noreferrer">Keep a Changelog</a>, and this project adheres to <a href="https://semver.org/spec/v2.0.0.html" target="_blank" rel="noreferrer">Semantic Versioning</a>.</p><h2 id="unreleased" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/utils-v1.6.2...HEAD" target="_blank" rel="noreferrer">Unreleased</a> <a class="header-anchor" href="#unreleased" aria-label="Permalink to “Unreleased”">​</a></h2><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to “Changed”">​</a></h3><ul><li><code>decodeBase64</code> and <code>encodeText</code> now return <code>Uint8Array&lt;ArrayBuffer&gt;</code>. The result passes to Web APIs such as <code>crypto.subtle.digest</code> without a cast under TypeScript 6 and later. The type declarations now need TypeScript 5.7 or later.</li><li>The README now has a When to use section. The section names the tasks that the package covers and the entry point of each task.</li></ul><h2 id="_1-6-2-2026-10-18" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/utils-v1.6.1...utils-v1.6.2" target="_blank" rel="noreferrer">1.6.2</a> - 2026-10-18 <a class="header-anchor" href="#_1-6-2-2026-10-18" aria-label="Permalink to “1.6.2 - 2026-10-18”">​</a></h2><h3 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to “Changed”">​</a></h3><ul><li><code>urlToRelativePath</code> no longer throws and catches a <code>TypeError</code> for a relative <code>url</code>. A call with a relative <code>url</code> now runs about 100 times faster in Node.js. CMCD encoding calls <code>urlToRelativePath</code> for <code>nor</code> values when the <code>baseUrl</code> option is set. The output does not change.</li></ul><h2 id="_1-6-1-2026-09-15" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/utils-v1.6.0...utils-v1.6.1" target="_blank" rel="noreferrer">1.6.1</a> - 2026-09-15 <a class="header-anchor" href="#_1-6-1-2026-09-15" aria-label="Permalink to “1.6.1 - 2026-09-15”">​</a></h2><h3 id="changed-2" tabindex="-1">Changed <a class="header-anchor" href="#changed-2" aria-label="Permalink to “Changed”">​</a></h3><ul><li>TSDoc: the comment prose is rewritten for readers who do not read English as a first language. Signatures, examples, tags, and links are unchanged.</li><li>README: the usage example prints its results instead of calling an undefined <code>assert</code>. Several of those calls compared typed arrays with <code>===</code>.</li></ul><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to “Fixed”">​</a></h3><ul><li><code>urlToRelativePath</code> removes every shared leading path segment. A base directory such as <code>/v/1080p/</code> returned <code>../1080p/seg-2.m4s</code> for a target in the same directory. The correct result is <code>seg-2.m4s</code>. A path that diverged and matched again deeper resolved to a wrong URL</li><li><code>urlToRelativePath</code> adds a <code>./</code> prefix when the result is empty, starts with <code>/</code>, or has <code>:</code> in its first segment. Without the prefix, the reference resolved to a wrong URL (RFC 3986 section 4.2)</li><li><code>encodeBase64</code> encodes inputs of any length. Before this change, it spread every byte into one <code>String.fromCharCode</code> call, which threw <code>RangeError: Maximum call stack size exceeded</code> at about 125 KB. It now converts the bytes in 32 KB chunks, which also runs about four times faster on small inputs. The output does not change.</li></ul><h2 id="_1-6-0-2026-07-28" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/utils-v1.5.1...utils-v1.6.0" target="_blank" rel="noreferrer">1.6.0</a> - 2026-07-28 <a class="header-anchor" href="#_1-6-0-2026-07-28" aria-label="Permalink to “1.6.0 - 2026-07-28”">​</a></h2><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to “Added”">​</a></h3><ul><li><code>DeepReadonly&lt;T&gt;</code> — marks every property of <code>T</code> as <code>readonly</code>, recursively. <code>Readonly&lt;T&gt;</code> stops at the top level, so a nested object stays writable and <code>value.nested.field = …</code> still compiles; this applies at every depth, including through arrays. Functions are left unchanged so callbacks carried on a value stay callable, and primitives are returned as they are</li></ul><h2 id="_1-5-1-2026-07-21" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/utils-v1.5.0...utils-v1.5.1" target="_blank" rel="noreferrer">1.5.1</a> - 2026-07-21 <a class="header-anchor" href="#_1-5-1-2026-07-21" aria-label="Permalink to “1.5.1 - 2026-07-21”">​</a></h2><h3 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to “Fixed”">​</a></h3><ul><li><code>uuid</code> no longer falls back to <code>Math.random</code>: when <code>crypto.randomUUID</code> is unavailable it derives the UUID from <code>crypto.getRandomValues</code> with RFC 4122 version/variant bits, keeping the blob-URL trick only as a last resort (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/388" target="_blank" rel="noreferrer">#388</a>)</li></ul><h2 id="_1-5-0-2026-05-13" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/utils-v1.4.0...utils-v1.5.0" target="_blank" rel="noreferrer">1.5.0</a> - 2026-05-13 <a class="header-anchor" href="#_1-5-0-2026-05-13" aria-label="Permalink to “1.5.0 - 2026-05-13”">​</a></h2><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to “Added”">​</a></h3><ul><li>Add <code>getBaseUrl(fullUrl)</code> to extract the origin and directory path from a full URL</li></ul><h3 id="fixed-2" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-2" aria-label="Permalink to “Fixed”">​</a></h3><ul><li><code>urlToRelativePath</code> now returns the input unchanged when it is already a relative path, instead of throwing <code>TypeError: Invalid URL</code> (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/364" target="_blank" rel="noreferrer">#364</a>)</li></ul><h2 id="_1-4-0-2026-02-11" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/utils-v1.3.0...utils-v1.4.0" target="_blank" rel="noreferrer">1.4.0</a> - 2026-02-11 <a class="header-anchor" href="#_1-4-0-2026-02-11" aria-label="Permalink to “1.4.0 - 2026-02-11”">​</a></h2><h3 id="added-2" tabindex="-1">Added <a class="header-anchor" href="#added-2" aria-label="Permalink to “Added”">​</a></h3><ul><li>Add <code>isArrayBufferLike</code> type guard utility function</li></ul><h3 id="fixed-3" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-3" aria-label="Permalink to “Fixed”">​</a></h3><ul><li>Loosen typed array generic parameters in <code>decodeText</code> and <code>stringToUint16</code></li></ul><h2 id="_1-3-0-2026-02-04" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/utils-v1.2.0...utils-v1.3.0" target="_blank" rel="noreferrer">1.3.0</a> - 2026-02-04 <a class="header-anchor" href="#_1-3-0-2026-02-04" aria-label="Permalink to “1.3.0 - 2026-02-04”">​</a></h2><h3 id="added-3" tabindex="-1">Added <a class="header-anchor" href="#added-3" aria-label="Permalink to “Added”">​</a></h3><ul><li>Add <code>HttpResponse</code> type</li><li>Add <code>HttpRequest</code> type</li><li>Add <code>ResponseTypeMap</code> type</li><li>Add <code>XmlNode</code> type</li><li>Add <code>stream</code> response type to <code>RequestResponseType</code></li></ul><h3 id="changed-3" tabindex="-1">Changed <a class="header-anchor" href="#changed-3" aria-label="Permalink to “Changed”">​</a></h3><ul><li>Rename <code>RequestType</code> to <code>RequestResponseType</code></li><li>Rename <code>Request</code> to <code>HttpRequest</code></li><li>Deprecate <code>Request</code> type</li></ul><h2 id="_1-2-0-2026-02-03" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/utils-v1.1.0...utils-v1.2.0" target="_blank" rel="noreferrer">1.2.0</a> - 2026-02-03 <a class="header-anchor" href="#_1-2-0-2026-02-03" aria-label="Permalink to “1.2.0 - 2026-02-03”">​</a></h2><h3 id="added-4" tabindex="-1">Added <a class="header-anchor" href="#added-4" aria-label="Permalink to “Added”">​</a></h3><ul><li>Add <code>ExclusiveRecord</code> type for creating records with exclusive keys</li></ul><h2 id="_1-1-0-2025-12-26" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/utils-v1.0.1...utils-v1.1.0" target="_blank" rel="noreferrer">1.1.0</a> - 2025-12-26 <a class="header-anchor" href="#_1-1-0-2025-12-26" aria-label="Permalink to “1.1.0 - 2025-12-26”">​</a></h2><h3 id="added-5" tabindex="-1">Added <a class="header-anchor" href="#added-5" aria-label="Permalink to “Added”">​</a></h3><ul><li>Add encodeText function to @svta/cml-utils (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/279" target="_blank" rel="noreferrer">#279</a>)</li></ul><h2 id="_1-0-1-2025-12-22" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/utils-v1.0.0...utils-v1.0.1" target="_blank" rel="noreferrer">1.0.1</a> - 2025-12-22 <a class="header-anchor" href="#_1-0-1-2025-12-22" aria-label="Permalink to “1.0.1 - 2025-12-22”">​</a></h2><h3 id="fixed-4" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-4" aria-label="Permalink to “Fixed”">​</a></h3><ul><li>Use fixed version numbers for all CML peer dependencies (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/277" target="_blank" rel="noreferrer">#277</a>)</li></ul><h2 id="_1-0-0-2025-10-24" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/tree/utils-v1.0.0" target="_blank" rel="noreferrer">1.0.0</a> - 2025-10-24 <a class="header-anchor" href="#_1-0-0-2025-10-24" aria-label="Permalink to “1.0.0 - 2025-10-24”">​</a></h2><h3 id="changed-4" tabindex="-1">Changed <a class="header-anchor" href="#changed-4" aria-label="Permalink to “Changed”">​</a></h3><ul><li>Remove CommonJS exports (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/192" target="_blank" rel="noreferrer">#192</a>)</li><li>Convert to mono-repo (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/238" target="_blank" rel="noreferrer">#238</a>)</li><li>Produce single bundled export for each package (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/260" target="_blank" rel="noreferrer">#260</a>)</li></ul>`,47)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};